import unicodedata
import hashlib
import hmac
import os
import re
import time
from functools import wraps
from flask import Flask, request, session, jsonify, abort, g
import bcrypt

app = Flask(__name__)
app.secret_key = os.urandom(32)

# User database (in production, use a real DB)
USERS = {
    "admin": {
        "password_hash": bcrypt.hashpw(b"super_secret_admin_pass", bcrypt.gensalt()),
        "role": "admin"
    },
    "user1": {
        "password_hash": bcrypt.hashpw(b"user_password_123", bcrypt.gensalt()),
        "role": "viewer"
    }
}

# Precomputed dummy hash used for constant-work timing defense on unknown users.
# Computed once at startup so the dummy path does the same kind of work as a
# real bcrypt.checkpw against a stored hash (no per-request gensalt()).
DUMMY_PASSWORD_HASH = bcrypt.hashpw(b"dummy", bcrypt.gensalt())

# Role-based access control matrix
ACL_RULES = {
    "/api/admin": ["admin"],
    "/api/admin/users": ["admin"],
    "/api/admin/config": ["admin"],
    "/api/data": ["admin", "viewer"],
    "/api/profile": ["admin", "viewer"],
}

def constant_time_compare(a, b):
    """Constant-time string comparison to prevent timing attacks."""
    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

def normalize_path(path):
    """Normalize URL path for consistent routing.
    Uses NFKC normalization to handle Unicode equivalences,
    then lowercases for case-insensitive matching."""
    # Remove double slashes
    path = re.sub(r'/+', '/', path)
    # Strip trailing slash
    path = path.rstrip('/')
    # Apply Unicode NFKC normalization for consistent representation
    path = unicodedata.normalize('NFKC', path)
    # Lowercase for case-insensitive routing
    path = path.lower()
    return path

def check_path_authorization(request_path, user_role):
    """Check if the user's role is authorized for the given path.
    Authorization is checked on the NORMALIZED path to prevent bypasses."""
    # Normalize the request path BEFORE checking against ACL
    normalized_request = normalize_path(request_path)

    for acl_path, allowed_roles in ACL_RULES.items():
        acl_normalized = acl_path.lower()
        # Check if normalized request path starts with the ACL path
        if normalized_request.startswith(acl_normalized):
            if user_role in allowed_roles:
                return True
            else:
                return False
    # Default deny for paths not in ACL
    return False

def require_auth(f):
    """Authentication and authorization middleware."""
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'username' not in session:
            return jsonify({"error": "Authentication required"}), 401

        username = session['username']
        if username not in USERS:
            session.clear()
            return jsonify({"error": "Invalid session"}), 401

        user_role = USERS[username]["role"]

        # Authorization check happens on the normalized path
        # to prevent Unicode-based bypasses
        raw_path = request.path

        if not check_path_authorization(raw_path, user_role):
            return jsonify({"error": "Forbidden"}), 403

        g.username = username
        g.user_role = user_role
        return f(*args, **kwargs)
    return decorated

@app.before_request
def apply_path_normalization():
    """Normalize the request path for routing purposes."""
    # Store original path for logging
    g.original_path = request.path
    # Apply normalization for route matching
    normalized = normalize_path(request.path)
    if normalized != request.path:
        # Update the request environment for routing
        request.environ['PATH_INFO'] = normalized

@app.route('/api/login', methods=['POST'])
def login():
    """Authenticate user with username and password."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({"error": "Missing credentials"}), 400

    username = data['username']
    password = data['password'].encode('utf-8')

    if username not in USERS:
        # Perform dummy bcrypt check against a precomputed hash to prevent
        # a timing oracle (no per-request salt generation).
        bcrypt.checkpw(password, DUMMY_PASSWORD_HASH)
        return jsonify({"error": "Invalid credentials"}), 401

    if bcrypt.checkpw(password, USERS[username]["password_hash"]):
        session['username'] = username
        session['login_time'] = time.time()
        return jsonify({"message": "Login successful", "role": USERS[username]["role"]})

    return jsonify({"error": "Invalid credentials"}), 401

@app.route('/api/admin', methods=['GET'])
@app.route('/api/admin/<path:subpath>', methods=['GET', 'POST'])
@require_auth
def admin_panel(subpath=None):
    """Admin-only endpoint for system management."""
    return jsonify({
        "message": "Admin panel access granted",
        "user": g.username,
        "subpath": subpath,
        "sensitive_config": {
            "db_host": "internal-db.corp.local",
            "api_keys": ["sk-prod-xxxx1234", "sk-prod-yyyy5678"],
            "internal_endpoints": ["/debug", "/metrics", "/healthz"]
        }
    })

@app.route('/api/data', methods=['GET'])
@require_auth
def get_data():
    """Data endpoint accessible by all authenticated users."""
    return jsonify({"data": "public dataset", "user": g.username})

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    """User profile endpoint."""
    return jsonify({
        "username": g.username,
        "role": g.user_role,
        "login_time": session.get('login_time')
    })

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
